const RenderShape = ({
  shape,
  color,
  size,
}: {
  shape: string;
  color?: string;
  size: number;
}) => {
  const c = color || "#059669";
  switch (shape) {
    case "square":
      return (
        <div
          style={{
            width: size,
            height: size,
            backgroundColor: c,
            borderRadius: "4px",
          }}
        />
      );
    case "circle":
      return (
        <div
          style={{
            width: size,
            height: size,
            backgroundColor: c,
            borderRadius: "50%",
          }}
        />
      );
    case "triangle":
      return (
        <div
          style={{
            width: 0,
            height: 0,
            borderLeft: `${size / 2}px solid transparent`,
            borderRight: `${size / 2}px solid transparent`,
            borderBottom: `${size}px solid ${c}`,
          }}
        />
      );
    case "star":
      return <Star fill={c} stroke="none" size={size} />;
    default:
      return null;
  }
};

