  // --- Firebase Debugging ---
  useEffect(() => {
    const testConnection = async () => {
      try {
        const { getDocFromServer } = await import("firebase/firestore");
        // Use a 15s timeout for the initial check to be more patient than the default 10s
        const connectPromise = getDocFromServer(
          doc(db, "system", "connection_test"),
        );
        const timeoutPromise = new Promise((_, reject) =>
          setTimeout(() => reject(new Error("Connection timeout")), 15000),
        );

        await Promise.race([connectPromise, timeoutPromise]).catch(
          (err: any) => {
            // If we get "not-found" or "permission-denied", it means we successfully reached the Firestore backend
            // but either the doc doesn't exist or we don't have access. Both are proof of connectivity.
            if (err.code === "not-found" || err.message?.includes("not-found"))
              return;
            if (
              err.code === "permission-denied" ||
              err.message?.includes("permission-denied")
            ) {
              console.warn(
                "Firestore reached, but permission was denied for connection test. Considering connected.",
              );
              return;
            }
            throw err;
          },
        );

        console.info("Firebase Firestore server connection active.");
        setFirestoreError(null);
        setFirestoreConnected(true);
      } catch (error: any) {
        // Log connection failure gracefully as info, as Firestore handles offline transitions seamlessly
        if (
          error.message?.includes("offline") ||
          error.message?.includes("timeout") ||
          error.message?.includes("Could not reach")
        ) {
          console.info(
            "Firestore is currently operating in offline caching mode. All operations will sync in the background.",
          );
        } else {
          console.warn(
            "Firestore connectivity warning:",
            error.message || error,
          );
        }
        setFirestoreConnected(false);
      }
    };
    testConnection();

    // Monitor standard browser online/offline status for dynamic UI updates
    const handleOnline = () => {
      setIsOnline(true);
      setFirestoreConnected(true);
    };
    const handleOffline = () => {
      setIsOnline(false);
      setFirestoreConnected(false);
    };

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    const handleConnChange = (e: any) => setIsOnline(e.detail);
    window.addEventListener("firestore-connection-changed", handleConnChange);

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
      window.removeEventListener(
        "firestore-connection-changed",
        handleConnChange,
      );
    };
  }, []);

  const handleEduError = (err: any, context: string) => {
    console.error(`${context} error:`, err);
    let errorMessage = `Failed to ${context.toLowerCase()}. Please try again.`;

    const errorStr = (err.message || String(err)).toLowerCase();
    if (errorStr.includes("api_key") || errorStr.includes("api key")) {
      errorMessage =
        "AI Service Error: Gemini API Key is missing or invalid. Please check your project secrets.";
    } else if (errorStr.includes("quota") || errorStr.includes("429")) {
      errorMessage =
        "AI Service Error: Quota exceeded. Please try again in a few minutes.";
    } else if (errorStr.includes("safety") || errorStr.includes("blocked")) {
      errorMessage =
        "AI Service Error: The model blocked the request due to safety filters (e.g. sensitive topics). Try a different prompt.";
    } else if (errorStr.includes("parsing") || errorStr.includes("json")) {
      errorMessage =
        "AI Service Error: The model provided an invalid response format. Please try again.";
    } else if (err.message) {
      errorMessage = `AI Error: ${err.message}`;
    }

    alert(errorMessage);
  };

  const getFriendlyAuthError = (err: any) => {
    const code = err?.code || "";
    const message = (err?.message || String(err)).toLowerCase();

    if (code === "auth/weak-password" || message.includes("weak-password"))
      return "Password must be at least 6 characters long.";
    if (
      code === "auth/email-already-in-use" ||
      message.includes("email-already-in-use")
    )
      return "This email is already registered. Please sign in instead.";
    if (code === "auth/invalid-email" || message.includes("invalid-email"))
      return "Please check your email format.";
    if (
      code === "auth/user-not-found" ||
      code === "auth/wrong-password" ||
      code === "auth/invalid-credential" ||
      message.includes("user-not-found") ||
      message.includes("wrong-password") ||
      message.includes("invalid-credential")
    ) {
      return "Invalid email or password. Please check your credentials or register if you do not have an account.";
    }
    if (
      code === "auth/operation-not-allowed" ||
      message.includes("operation-not-allowed")
    )
      return "Email/Password sign-in is not enabled. Please contact support.";
    if (
      code === "auth/network-request-failed" ||
      message.includes("network-request-failed")
    )
      return "Network error. Please check your internet connection.";
    return err?.message || String(err);
  };

