  // Sync weekly arrays with sessionWeeks
  useEffect(() => {
    setLpUnit((prev) => {
      if (prev.length === sessionWeeks) return prev;
      if (prev.length < sessionWeeks)
        return [...prev, ...Array(sessionWeeks - prev.length).fill("")];
      return prev.slice(0, sessionWeeks);
    });
    setLpWeeklyTopics((prev) => {
      if (prev.length === sessionWeeks) return prev;
      if (prev.length < sessionWeeks)
        return [...prev, ...Array(sessionWeeks - prev.length).fill("")];
      return prev.slice(0, sessionWeeks);
    });
    setLpActivities((prev) => {
      if (prev.length === sessionWeeks) return prev;
      if (prev.length < sessionWeeks)
        return [...prev, ...Array(sessionWeeks - prev.length).fill("")];
      return prev.slice(0, sessionWeeks);
    });
    setLpWeekLabels((prev) => {
      if (prev.length === sessionWeeks) return prev;
      if (prev.length < sessionWeeks) {
        const next = [...prev];
        for (let i = prev.length; i < sessionWeeks; i++)
          next.push(`Week ${i + 1}`);
        return next;
      }
      return prev.slice(0, sessionWeeks);
    });
  }, [sessionWeeks]);

  // Undo/Redo State
  const [historyStack, setHistoryStack] = useState<EduContent[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);
  const isInternalUpdate = useRef(false);

  const pushToHistory = (newContent: EduContent) => {
    if (isInternalUpdate.current) return;
    setHistoryStack((prev) => {
      const newStack = prev.slice(0, historyIndex + 1);
      newStack.push(JSON.parse(JSON.stringify(newContent)));
      if (newStack.length > 50) newStack.shift();
      return newStack;
    });
    setHistoryIndex((prev) => Math.min(prev + 1, 49));
  };

  // Auth Handler (Passwordless OTP based)
  const handleRequestOtp = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError("");
    setShowLegacyPasswordField(false);

    const cleanEmail = email.trim();
    if (!cleanEmail) {
      setAuthError("Email address is required.");
      return;
    }

    setIsSendingOtp(true);
    try {
      const res = await fetch("/api/auth/send-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email: cleanEmail,
          customBaseUrl: apiSyncBaseUrl,
          customToken: apiSyncToken,
        }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to send OTP verification code.");
      }

      setOtpSent(true);
    } catch (err: any) {
      setAuthError(err.message || "An error occurred while sending the code.");
      console.error("OTP send error:", err);
    } finally {
      setIsSendingOtp(false);
    }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError("");
    setIsVerifyingOtp(true);

    const cleanEmail = email.trim();

    // If legacy password update is triggered
    if (showLegacyPasswordField) {
      if (!legacyPassword) {
        setAuthError(
          "Please enter your existing password to convert your account.",
        );
        setIsVerifyingOtp(false);
        return;
      }
      try {
        const res = await signInWithEmailAndPassword(
          auth,
          cleanEmail,
          legacyPassword,
        );
        const { updatePassword } = await import("firebase/auth");
        await updatePassword(res.user, cleanEmail + "_EduMagicOTPSecret!");

        if (res.user.displayName) {
          setTeacherName(res.user.displayName);
        } else if (res.user.email) {
          setTeacherName(res.user.email.split("@")[0]);
        }

        setOtpSent(false);
        setOtpCode("");
        setShowLegacyPasswordField(false);
        setLegacyPassword("");
      } catch (pwErr: any) {
        setAuthError(getFriendlyAuthError(pwErr));
        console.error("Legacy conversion error:", pwErr);
      } finally {
        setIsVerifyingOtp(false);
      }
      return;
    }

    if (!otpCode || otpCode.trim().length !== 6) {
      setAuthError("Please enter a valid 6-digit verification code.");
      setIsVerifyingOtp(false);
      return;
    }

    try {
      const response = await fetch("/api/auth/verify-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: cleanEmail, code: otpCode.trim() }),
      });

      const resData = await response.json();
      if (!response.ok) {
        throw new Error(resData.error || "Failed to verify OTP code.");
      }

      const securePassword = cleanEmail + "_EduMagicOTPSecret!";
      try {
        const userCredential = await signInWithEmailAndPassword(
          auth,
          cleanEmail,
          securePassword,
        );

        if (userCredential.user.displayName) {
          setTeacherName(userCredential.user.displayName);
        } else if (userCredential.user.email) {
          setTeacherName(userCredential.user.email.split("@")[0]);
        }

        setOtpSent(false);
        setOtpCode("");
      } catch (authErr: any) {
        if (
          authErr.code === "auth/user-not-found" ||
          authErr.message?.includes("user-not-found")
        ) {
          const userCredential = await createUserWithEmailAndPassword(
            auth,
            cleanEmail,
            securePassword,
          );
          await updateProfile(userCredential.user, {
            displayName: resData.name,
          });
          setTeacherName(resData.name);

          const rolesToSave =
            resData.role === "admin" ? ["admin", "educator"] : ["educator"];
          try {
            await setDoc(doc(db, "users", userCredential.user.uid), {
              uid: userCredential.user.uid,
              email: cleanEmail,
              teacherName: resData.name,
              roles: rolesToSave,
              createdAt: new Date().toISOString(),
            });
            setUserRoles(rolesToSave);
          } catch (fsErr) {
            handleFirestoreError(
              fsErr,
              OperationType.WRITE,
              `users/${userCredential.user.uid}`,
            );
          }

          setOtpSent(false);
          setOtpCode("");
        } else if (
          authErr.code === "auth/wrong-password" ||
          authErr.message?.includes("wrong-password")
        ) {
          setShowLegacyPasswordField(true);
          setAuthError(
            "This account was created under the legacy system. Please enter your existing password once to convert it to secure passwordless log in.",
          );
        } else {
          throw authErr;
        }
      }
    } catch (err: any) {
      setAuthError(
        err.message ||
          "Verification failed. Please check your code and try again.",
      );
      console.error("OTP Verification Error:", err);
    } finally {
      setIsVerifyingOtp(false);
    }
  };

  const handleResetPassword = async (e: React.MouseEvent) => {
    e.preventDefault();
    setAuthError("");
    setResetEmailSent(false);
    setResetMessage("Contact your administrator.");
    alert("Contact your administrator.");
  };

  const handlePasswordAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError("");
    setIsVerifyingOtp(true); // Re-use loading state to disable submission button

    const cleanEmail = email.trim();
    if (!cleanEmail || !password) {
      setAuthError("Email and password are required.");
      setIsVerifyingOtp(false);
      return;
    }

    try {
      if (authMode === "register") {
        if (!registerName) {
          throw new Error("Display Name is required for registration.");
        }

        // Validate admin registration permissions securely checking if they are already registered in the Firebase Firestore users collection
        let rolesToSave = [...registerRoles];
        if (rolesToSave.includes("admin")) {
          const { query, collection, where, getDocs } =
            await import("firebase/firestore");
          const usersRef = collection(db, "users");
          const q = query(
            usersRef,
            where("email", "==", cleanEmail.toLowerCase()),
          );
          const querySnapshot = await getDocs(q);

          if (querySnapshot.empty) {
            throw new Error(
              "Only users who are already registered in Firebase can register as Admin. Other than that you can register as Educator only.",
            );
          }
        }

        const res = await createUserWithEmailAndPassword(
          auth,
          cleanEmail,
          password,
        );
        await updateProfile(res.user, { displayName: registerName });
        setTeacherName(registerName);

        try {
          await setDoc(doc(db, "users", res.user.uid), {
            uid: res.user.uid,
            email: cleanEmail,
            teacherName: registerName,
            roles: rolesToSave,
            createdAt: new Date().toISOString(),
          });
          setUserRoles(rolesToSave);
        } catch (fsErr) {
          handleFirestoreError(
            fsErr,
            OperationType.WRITE,
            `users/${res.user.uid}`,
          );
        }
      } else {
        const res = await signInWithEmailAndPassword(
          auth,
          cleanEmail,
          password,
        );
        const fallbackName =
          res.user.displayName || res.user.email?.split("@")[0] || "Educator";
        setTeacherName(fallbackName);

        try {
          const docSnap = await getDoc(doc(db, "users", res.user.uid));
          if (docSnap.exists()) {
            const data = docSnap.data();
            if (data?.teacherName) {
              setTeacherName(data.teacherName);
            }
            if (data?.roles) {
              setUserRoles(data.roles);
            }
          }
        } catch (fsErr) {
          console.error("Failed to load user profile roles:", fsErr);
        }
      }
    } catch (err: any) {
      setAuthError(getFriendlyAuthError(err));
      console.error("Standard Auth Error:", err);
    } finally {
      setIsVerifyingOtp(false);
    }
  };

  const handleLogout = async () => {
    await signOut(auth);
    setUser(null);
    setTeacherName("Teacher");
    clearWorkspace();
    setCurrentView("home");
  };

  // Auth Listener
  useEffect(() => {
    // Immediate check for incoming SSO redirected user payload override
    const params = new URLSearchParams(window.location.search);
    if (params.has("sso_user")) {
      try {
        const ssoStr = params.get("sso_user");
        if (ssoStr) {
          const rawUser = JSON.parse(atob(ssoStr));
          const ssoFakeFbUser: any = {
            uid: rawUser.sub,
            email: rawUser.email,
            displayName: `${rawUser.name.first_name} ${rawUser.name.last_name}`,
            emailVerified: true,
            isSsoUser: true,
            ssoProfile: rawUser
          };
          setUser(ssoFakeFbUser);
          setTeacherName(`${rawUser.name.first_name} ${rawUser.name.last_name}`);
          // SSO users are regular educators in their own private space —
          // admin (which can see all teachers' submissions) is granted only
          // to the designated admin emails, same as the normal login path.
          setUserRoles(
            ADMIN_EMAILS.includes((rawUser.email || "").toLowerCase())
              ? ["admin", "educator"]
              : ["educator"],
          );
          setAuthLoading(false);
          
          window.history.replaceState({}, document.title, window.location.pathname);
          return;
        }
      } catch (err) {
        console.error("SSO user payload parser error", err);
      }
    }

    const unsubscribe = onAuthStateChanged(auth, async (fbUser) => {
      setUser(fbUser);
      if (fbUser) {
        // Immediate fallback from Auth profile
        const fallbackName =
          fbUser.displayName || fbUser.email?.split("@")[0] || "Educator";
        setTeacherName(fallbackName);

        // Fetch teacher name from Firestore profile
        try {
          const userDoc = await getDoc(doc(db, "users", fbUser.uid));

          let isAuthorizedObj = ADMIN_EMAILS.includes(
            fbUser.email?.toLowerCase() || "",
          );
          if (!isAuthorizedObj && fbUser.email) {
            try {
              const resValidation = await fetch(
                "/api/auth/check-registration",
                {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({ email: fbUser.email }),
                },
              );
              if (resValidation.ok) {
                const valData = await resValidation.json();
                isAuthorizedObj = valData.success && valData.role === "admin";
              }
            } catch (ttErr) {
              console.error(
                "Failed to validate admin role on registration check server-side:",
                ttErr,
              );
            }
          }

          if (userDoc.exists()) {
            const data = userDoc.data();
            if (data.teacherName) {
              setTeacherName(data.teacherName);
            }

            let consolidatedRoles = data.roles ? [...data.roles] : ["educator"];
            if (isAuthorizedObj) {
              if (!consolidatedRoles.includes("admin")) {
                consolidatedRoles.push("admin");
              }
            } else {
              consolidatedRoles = consolidatedRoles.filter(
                (r) => r !== "admin",
              );
            }

            if (consolidatedRoles.length === 0) {
              consolidatedRoles = ["educator"];
            }

            // Sync back to firestore if roles have changed
            const rolesHaveChanged =
              JSON.stringify(consolidatedRoles.sort()) !==
              JSON.stringify((data.roles || []).sort());
            if (rolesHaveChanged) {
              try {
                await setDoc(
                  doc(db, "users", fbUser.uid),
                  { roles: consolidatedRoles },
                  { merge: true },
                );
              } catch (setErr) {
                console.error(
                  "Failed to update corrected roles in db:",
                  setErr,
                );
              }
            }

            setUserRoles(consolidatedRoles);
          } else {
            // Case where document doesn't exist yet but let's check auth
            const consolidatedRoles = isAuthorizedObj
              ? ["admin", "educator"]
              : ["educator"];
            setUserRoles(consolidatedRoles);
          }
        } catch (err: any) {
          if (err.message?.includes("offline")) {
            console.warn("Firestore is offline, using auth profile fallback.");
          } else {
            console.error("Error fetching user profile:", err);
          }

          if (ADMIN_EMAILS.includes(fbUser.email?.toLowerCase() || "")) {
            setUserRoles(["admin", "educator"]);
          } else {
            setUserRoles(["educator"]);
          }
        }
      } else {
        setTeacherName("Guest");
      }
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  const undo = () => {
    if (historyIndex > 0) {
      isInternalUpdate.current = true;
      const prevIndex = historyIndex - 1;
      const prevContent = JSON.parse(JSON.stringify(historyStack[prevIndex]));
      setContent(prevContent);
      setHistoryIndex(prevIndex);
      setTimeout(() => {
        isInternalUpdate.current = false;
      }, 100);
    }
  };

  const redo = () => {
    if (historyIndex < historyStack.length - 1) {
      isInternalUpdate.current = true;
      const nextIndex = historyIndex + 1;
      const nextContent = JSON.parse(JSON.stringify(historyStack[nextIndex]));
      setContent(nextContent);
      setHistoryIndex(nextIndex);
      setTimeout(() => {
        isInternalUpdate.current = false;
      }, 100);
    }
  };

  // Auto-save to history stack with debounce
  const lastSavedContent = useRef<string>("");
  useEffect(() => {
    if (!content || isInternalUpdate.current) return;

    const handler = setTimeout(() => {
      const currentStr = JSON.stringify(content);
      if (currentStr !== lastSavedContent.current) {
        pushToHistory(content);
        lastSavedContent.current = currentStr;
      }
    }, 1000); // Debounce 1s

    return () => clearTimeout(handler);
  }, [content]);

  useEffect(() => {
    const handleGlobalPaste = async (e: ClipboardEvent) => {
      // Don't handle paste if it's in an input or textarea (unless it's our specific manualLink field maybe, but better to just let native behavior handle that)
      const activeElement = document.activeElement as HTMLElement;
      if (
        activeElement &&
        (activeElement.tagName === "INPUT" ||
          activeElement.tagName === "TEXTAREA" ||
          activeElement.isContentEditable)
      ) {
        return;
      }

      if (!content) return;

      const items = e.clipboardData?.items;
      if (!items) return;

      let foundImage = false;
      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf("image") !== -1) {
          const blob = items[i].getAsFile();
          if (blob) {
            const reader = new FileReader();
            reader.onload = (event) => {
              const base64 = event.target?.result as string;
              addSlideImage(base64);
            };
            reader.readAsDataURL(blob);
            foundImage = true;
            break; // Prioritize image blob over text URL if both present
          }
        }
      }

      if (!foundImage) {
        for (let i = 0; i < items.length; i++) {
          if (items[i].type === "text/plain") {
            items[i].getAsString((text) => {
              const trimmed = text.trim();
              if (
                trimmed.startsWith("http") ||
                trimmed.startsWith("data:image")
              ) {
                // Simple validation to avoid accidentally pasting long texts that happen to start with http
                if (trimmed.length < 2048) {
                  addSlideImage(trimmed);
                }
              }
            });
          }
        }
      }
    };

    window.addEventListener("paste", handleGlobalPaste);
    return () => window.removeEventListener("paste", handleGlobalPaste);
  }, [content, currentSlideIdx]);

  // Global keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === "z") {
        if (e.shiftKey) {
          redo();
        } else {
          undo();
        }
      } else if ((e.ctrlKey || e.metaKey) && e.key === "y") {
        redo();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [historyIndex, historyStack]);
  const [templateUploadMode, setTemplateUploadMode] = useState<
    "strict" | "custom"
  >("strict");
  const [fileContext, setFileContext] = useState<{
    mimeType: string;
    data: any;
    name: string;
  } | null>(null);
  const [selectedQuestionTypes, setSelectedQuestionTypes] = useState<string[]>([
    "Multiple Choice",
    "Short Answer",
  ]);
  // How many questions of each type to generate. The total (numQuestions) and
  // the selected types are kept in sync from this.
  const [typeCounts, setTypeCounts] = useState<Record<string, number>>({
    "Multiple Choice": 3,
    "Short Answer": 2,
  });
  // Total used when NO per-type counts are chosen — question types become
  // automatic and the model picks a suitable mix for this many questions.
  const [autoQuestionCount, setAutoQuestionCount] = useState(10);
  useEffect(() => {
    const types = Object.keys(typeCounts).filter((t) => typeCounts[t] > 0);
    setSelectedQuestionTypes(types);
    const sum = types.reduce((s, t) => s + (typeCounts[t] || 0), 0);
    // When the teacher leaves every type at 0, types are automatic — keep a
    // sensible total instead of collapsing to 0 (which would generate nothing).
    setNumQuestions(sum > 0 ? sum : autoQuestionCount);
  }, [typeCounts, autoQuestionCount]);
  // Differentiated assessment levels — same worksheet reworded per Lexile band
  const [wsLevels, setWsLevels] = useState<string[]>([
    "200-300",
    "400-500",
    "600-700",
  ]);
  const [isLevelingWorksheet, setIsLevelingWorksheet] = useState(false);
