  const loadProject = (project: any, reviewMode: boolean = false) => {
    setCurrentProjectId(project.id);
    setContent(project.content);
    setIsReviewMode(reviewMode);
    setWorkspaceMode(
      project.category || project.settings?.workspaceMode || "slides",
    );
    setIncludeStory(project.settings?.includeStory || false);
    setIsTemplateMode(project.settings?.isTemplateMode || false);

    // Navigate to the correct view
    if (project.category === "lesson-plan") setCurrentView("lesson-plan");
    else if (project.category === "slides") setCurrentView("slides");
    else if (project.category === "worksheet") setCurrentView("worksheet");
    else if (project.category === "notes") setCurrentView("notes");
    else if (project.category === "reading-program") setCurrentView("reading-program");
    else setCurrentView("slides");
  };

  const deleteSubmittedPlan = async (planId: string) => {
    if (
      !window.confirm(
        "Are you sure you want to delete this submitted plan? This action cannot be undone.",
      )
    )
      return;

    try {
      await deleteDoc(doc(db, "submitted_plans", planId));
      alert("Successfully deleted the submitted plan.");
    } catch (err) {
      console.error("Error deleting plan:", err);
      alert("Failed to delete the plan. Check permissions.");
    }
  };

  const createSubmittedFolder = async () => {
    const name = prompt("Folder name? (e.g. Teacher Name or Status)");
    if (!name) return;

    try {
      await addDoc(collection(db, "submitted_folders"), {
        name,
        createdAt: Date.now(),
        createdBy: user?.email,
      });
    } catch (err) {
      console.error("Error creating folder:", err);
      alert("Failed to create folder.");
    }
  };

  const deleteSubmittedFolder = async (folderId: string) => {
    const folder = submittedFolders.find((f) => f.id === folderId);
    if (!folder) return;

    if (
      !window.confirm(
        `Are you sure you want to delete the folder "${folder.name}"? Plans inside will remain but become unorganized.`,
      )
    )
      return;

    try {
      // Unset folderId for plans in this folder
      const batch: any[] = [];
      submittedProjects.forEach((p) => {
        if (p.folderId === folderId) {
          batch.push(
            updateDoc(doc(db, "submitted_plans", p.id), { folderId: null }),
          );
        }
      });
      await Promise.all(batch);
      await deleteDoc(doc(db, "submitted_folders", folderId));
      if (currentSubmittedFolderId === folderId)
        setCurrentSubmittedFolderId(null);
    } catch (err) {
      console.error("Error deleting folder:", err);
      alert("Failed to delete folder.");
    }
  };

