  // Synchronize state with URL hash to support browser level back button events in sandboxed preview environments
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace("#", "");
      const validViews = [
        "home",
        "educator-suite",
        "admin",
        "lesson-plan",
        "slides",
        "worksheet",
        "notes",
        "reading-program",
      ];
      if (hash && validViews.includes(hash)) {
        setCurrentView((prev) => {
          if (prev !== hash) {
            return hash as any;
          }
          return prev;
        });
      } else if (!hash) {
        setCurrentView("home");
      }
    };

    window.addEventListener("hashchange", handleHashChange);

    // Check hash on load
    const initialHash = window.location.hash.replace("#", "");
    const validViews = [
      "home",
      "educator-suite",
      "admin",
      "lesson-plan",
      "slides",
      "worksheet",
      "notes",
      "reading-program",
    ];
    if (initialHash && validViews.includes(initialHash)) {
      setCurrentView(initialHash as any);
    }

    return () => window.removeEventListener("hashchange", handleHashChange);
  }, []);

