  const getRemainingPeriods = (
    teacherId: string,
    subject: string,
    yg: string,
  ) => {
    const quota = assignmentQuotas.find(
      (q) =>
        q.teacherId === teacherId &&
        q.subject === subject &&
        q.yearGroup === yg,
    );
    if (!quota) return 0;

    // Count how many times this (teacher, sub, yg) is in the grid
    let used = 0;
    const yearData = timetableGrid[yg] || {};
    (Object.values(yearData) as any[][]).forEach((daySlots) => {
      daySlots.forEach((slot: any) => {
        if (slot) {
          const arr = Array.isArray(slot) ? slot : [slot];
          arr.forEach((item: any) => {
            if (
              item &&
              item.teacherId === teacherId &&
              item.subject === subject
            ) {
              used++;
            }
          });
        }
      });
    });

    return quota.total - used;
  };

