                            const ids = val.split(",").map((id) => id.trim());
                            if (ids.includes(teacher.id)) {
                              const parts = key.split("-");
                              if (parts.length >= 2) {
                                const subName = parts.slice(1).join("-");
                                if (!seen.has(subName)) {
                                  seen.add(subName);
                                  assignedSubjects.push(subName);
                                }
                              }
                            }
